        is Offline -> (4 + Utf8Codec.maxBytes(message))
        is IoError -> (4 + Utf8Codec.maxBytes(message))
        is CacheError -> (4 + Utf8Codec.maxBytes(message))
        is PipelineError -> (4 + Utf8Codec.maxBytes(message))
        is CircuitOpen -> (4 + Utf8Codec.maxBytes(message))
        is RateLimited -> 8
        is Timeout -> 8
        is MissingArtifact -> (4 + Utf8Codec.maxBytes(message))
        is UnsupportedModelCapability -> (4 + Utf8Codec.maxBytes(message))
        is UnsupportedBackendCapability -> (4 + Utf8Codec.maxBytes(message))
        is InvalidImage -> (4 + Utf8Codec.maxBytes(message))
    }

    fun wireEncodeTo(wire: WireWriter) {
        when (this) {
            is ModelNotFound -> {
                wire.writeI32(0)
                wire.writeString(id)
            }
            is DirectoryNotFound -> {
                wire.writeI32(1)
                wire.writeString(path)
            }
            is MetadataNotFound -> {
                wire.writeI32(2)
                wire.writeString(path)
            }
            is MetadataInvalid -> {
                wire.writeI32(3)
                wire.writeString(message)
            }
            is LoadError -> {
                wire.writeI32(4)
                wire.writeString(message)
            }
            is InferenceError -> {
                wire.writeI32(5)
                wire.writeString(message)
            }
            is AbortedForCloudFallback -> {
                wire.writeI32(6)
                wire.writeString(reason)
            }
            is StreamingNotSupported -> wire.writeI32(7)
            is NotLoaded -> wire.writeI32(8)
            is ConfigError -> {
                wire.writeI32(9)
                wire.writeString(message)
            }
            is NetworkError -> {
                wire.writeI32(10)
                wire.writeString(message)
            }
            is Offline -> {
                wire.writeI32(11)
                wire.writeString(message)
            }
            is IoError -> {
                wire.writeI32(12)
                wire.writeString(message)
            }
            is CacheError -> {
                wire.writeI32(13)
                wire.writeString(message)
            }
            is PipelineError -> {
                wire.writeI32(14)
                wire.writeString(message)
            }
            is CircuitOpen -> {
                wire.writeI32(15)
                wire.writeString(message)
            }
            is RateLimited -> {
                wire.writeI32(16)
                wire.writeU64(retryAfterSecs)
            }
            is Timeout -> {
                wire.writeI32(17)
                wire.writeU64(timeoutMs)
            }
            is MissingArtifact -> {
                wire.writeI32(18)
                wire.writeString(message)
            }
            is UnsupportedModelCapability -> {
                wire.writeI32(19)
                wire.writeString(message)
            }
            is UnsupportedBackendCapability -> {
                wire.writeI32(20)
                wire.writeString(message)
            }
            is InvalidImage -> {
                wire.writeI32(21)
                wire.writeString(message)
            }
        }
    }
}

sealed class XybridEnvelopeKind {

    data class Text(val text: String) : XybridEnvelopeKind()

    data class Audio(val bytes: ByteArray) : XybridEnvelopeKind()

    data class Embedding(val values: FloatArray) : XybridEnvelopeKind()

    data class Image(val bytes: ByteArray, val format: String) : XybridEnvelopeKind()

    data class MultiPart(val parts: List<XybridEnvelope>) : XybridEnvelopeKind()

    companion object {
        fun decode(reader: WireReader): XybridEnvelopeKind {
            val tag = reader.readI32()
            return when (tag) {
                0 -> {
                    Text(
                        reader.readString()
                    )
                }
                1 -> {
                    Audio(
                        reader.readBytes()
                    )
                }
                2 -> {
                    Embedding(
                        reader.readFloatArray()
                    )
                }
                3 -> {
                    Image(
                        reader.readBytes(),
                        reader.readString()
                    )
                }
                4 -> {
                    MultiPart(
                        reader.readList { XybridEnvelope.decode(reader) }
                    )
                }
                else -> throw FfiException(-1, "Unknown XybridEnvelopeKind tag: $tag")
            }
        }
    }

    fun wireEncodedSize(): Int = 4 + when (this) {
        is Text -> (4 + Utf8Codec.maxBytes(text))
        is Audio -> (4 + bytes.size)
        is Embedding -> (4 + values.size * 4)
        is Image -> (4 + bytes.size) + (4 + Utf8Codec.maxBytes(format))
        is MultiPart -> (4 + parts.sumOf { item -> item.wireEncodedSize() })
    }

    fun wireEncodeTo(wire: WireWriter) {
        when (this) {
            is Text -> {
                wire.writeI32(0)
                wire.writeString(text)
            }
            is Audio -> {
                wire.writeI32(1)
                wire.writePrimitiveList(bytes)
            }
            is Embedding -> {
                wire.writeI32(2)
                wire.writePrimitiveList(values)
            }
            is Image -> {
                wire.writeI32(3)
                wire.writePrimitiveList(bytes)
                wire.writeString(format)
            }
            is MultiPart -> {
                wire.writeI32(4)
                wire.writeU32(parts.size.toUInt()); parts.forEach { item -> item.wireEncodeTo(wire) }
            }
        }
    }
}

